/**
 * Scaffold a fresh `infra.config.ts` from the preset catalog — so clinozy-infra drops
 * into a new project with its resource composition ready to edit. Generated by the
 * init wizard only when the file is absent (never overwrites a curated one).
 */
import type { Preset } from '@setup/presets/index.js';

/** Preset key → its exported binding name, e.g. `github-app-with-oauth` → `githubAppWithOauthPreset`. */
export function presetExportName(key: string): string {
  const camel = key.replace(/-([a-z])/g, (_m, c: string) => c.toUpperCase());
  return `${camel}Preset`;
}

/** Render a canonical `infra.config.ts` listing every preset in catalog order. Pure. */
export function renderInfraConfigTs(presets: readonly Preset[]): string {
  const names = presets.map((p) => presetExportName(p.key));
  return [
    '/**',
    ' * infra.config.ts — the RESOURCE composition for clinozy-infra (generated by init).',
    ' *',
    ' * Edit this file to add/remove/reorder a provisioned service — deleting a line',
    ' * removes it from plan/up. Project identity lives in setup.config.json.',
    ' */',
    "import { defineInfraConfig } from './src/infra/infra-config.js';",
    'import {',
    ...names.map((n) => `  ${n},`),
    "} from './src/presets/index.js';",
    '',
    'export default defineInfraConfig({',
    '  // Both targets currently use `.env.<environment>`; clinozy-fe receives only VITE_* keys.',
    '  envFiles: {',
    '    backend: (env) => `.env.${env}`,',
    '    frontend: (env) => `.env.${env}`,',
    '  },',
    '  // Order matters — providers run sequentially in the provision loop.',
    '  resources: () => [',
    ...names.map((n) => `    ${n},`),
    '  ],',
    '});',
    '',
  ].join('\n');
}
